<?php

declare(strict_types=1);

use Illuminate\Foundation\Testing\RefreshDatabase;
use Inertia\Testing\AssertableInertia;
use Modules\Task\Models\Task;
use Yuan\AdminCore\Audit\ImmutableActivity;
use Yuan\AdminCore\Testing\ModuleAssertions;

use function Pest\Laravel\delete;
use function Pest\Laravel\get;
use function Pest\Laravel\post;
use function Pest\Laravel\put;

// Kanban (generated by make:module): the AGENTS §8 cases for each declared action.

uses(RefreshDatabase::class);

/**
 * A valid form submission, as the create page sends it.
 *
 * @param  array<string, mixed>  $overrides
 * @return array<string, mixed>
 */
function taskInput(array $overrides = []): array
{
    return [
        'title' => 'Contoh Title',
        'description' => 'Catatan contoh',
        'status' => 'rencana',
        'priority' => 'rendah',
        'assignee' => 'Contoh Assignee',
        'due_on' => '2026-10-20',
        'position' => 12,
        ...$overrides,
    ];
}

it('redirects guests to login', function (): void {
    $task = Task::factory()->create();

    ModuleAssertions::assertGuestRedirected('get', '/admin/kanban');
    ModuleAssertions::assertGuestRedirected('get', "/admin/kanban/{$task->id}");
    ModuleAssertions::assertGuestRedirected('get', '/admin/kanban/create');
    ModuleAssertions::assertGuestRedirected('post', '/admin/kanban');
    ModuleAssertions::assertGuestRedirected('get', "/admin/kanban/{$task->id}/edit");
    ModuleAssertions::assertGuestRedirected('put', "/admin/kanban/{$task->id}");
    ModuleAssertions::assertGuestRedirected('delete', "/admin/kanban/{$task->id}");
    ModuleAssertions::assertGuestRedirected('delete', '/admin/kanban');
});

it('needs the permission of each action', function (): void {
    $task = Task::factory()->create();

    ModuleAssertions::assertForbiddenWithout('kanban.view', 'get', '/admin/kanban');
    ModuleAssertions::assertForbiddenWithout('kanban.view', 'get', "/admin/kanban/{$task->id}");
    ModuleAssertions::assertForbiddenWithout('kanban.create', 'get', '/admin/kanban/create');
    ModuleAssertions::assertForbiddenWithout('kanban.create', 'post', '/admin/kanban', taskInput());
    ModuleAssertions::assertForbiddenWithout('kanban.edit', 'get', "/admin/kanban/{$task->id}/edit");
    ModuleAssertions::assertForbiddenWithout('kanban.edit', 'put', "/admin/kanban/{$task->id}", taskInput(['lock_version' => $task->lock_version]));
    ModuleAssertions::assertForbiddenWithout('kanban.delete', 'delete', "/admin/kanban/{$task->id}");
    ModuleAssertions::assertForbiddenWithout('kanban.delete', 'delete', '/admin/kanban', ['ids' => [$task->id]]);

    expect($task->fresh()?->trashed())->toBeFalse();
});

it('lists and shows kanban records', function (): void {
    $task = Task::factory()->create();
    ModuleAssertions::actingAsLevelWith(['kanban.view']);

    AssertableInertia::fromTestResponse(get('/admin/kanban')->assertOk())
        ->component('Task::Index')
        ->count('tasks.items', 1)
        ->where('tasks.items.0.id', $task->id);

    AssertableInertia::fromTestResponse(get("/admin/kanban/{$task->id}")->assertOk())
        ->component('Task::Show')
        ->where('task.id', $task->id)
        ->where('breadcrumbs.items.1.label', $task->auditLabel());
});

it('rejects a sort the list does not allow', function (): void {
    ModuleAssertions::actingAsLevelWith(['kanban.view']);

    get('/admin/kanban?sort=lock_version')->assertStatus(400);
});

it('scopes every kanban query to the signed-in user', function (): void {
    $task = Task::factory()->create();
    ModuleAssertions::actingAsLevelWith(['kanban.view', 'kanban.create', 'kanban.edit', 'kanban.delete']);

    ModuleAssertions::assertScopedToUser(Task::class, 'get', '/admin/kanban');
    ModuleAssertions::assertScopedToUser(Task::class, 'get', "/admin/kanban/{$task->id}");
    ModuleAssertions::assertScopedToUser(Task::class, 'get', "/admin/kanban/{$task->id}/edit");
    ModuleAssertions::assertScopedToUser(Task::class, 'put', "/admin/kanban/{$task->id}", taskInput(['lock_version' => $task->lock_version]));
    ModuleAssertions::assertScopedToUser(Task::class, 'delete', '/admin/kanban', ['ids' => [$task->id]]);
    ModuleAssertions::assertScopedToUser(Task::class, 'delete', "/admin/kanban/{$task->id}");
});

it('creates a kanban and audits it', function (): void {
    ModuleAssertions::actingAsLevelWith(['kanban.view', 'kanban.create']);

    post('/admin/kanban', taskInput())->assertSessionHasNoErrors()->assertRedirect();

    $task = Task::query()->sole();
    ModuleAssertions::assertAudited($task, 'created');
});

it('rejects a kanban without its required fields', function (): void {
    ModuleAssertions::actingAsLevelWith(['kanban.view', 'kanban.create']);

    post('/admin/kanban', [])->assertSessionHasErrors(['title', 'status', 'priority', 'position']);

    expect(Task::query()->count())->toBe(0);
});

it('updates a kanban and audits the change', function (): void {
    $task = Task::factory()->create();
    ModuleAssertions::actingAsLevelWith(['kanban.view', 'kanban.edit']);

    AssertableInertia::fromTestResponse(get("/admin/kanban/{$task->id}/edit")->assertOk())
        ->component('Task::Edit')
        ->where('task.lock_version', 0);

    put("/admin/kanban/{$task->id}", taskInput(['lock_version' => $task->lock_version]))
        ->assertSessionHasNoErrors()
        ->assertRedirect("/admin/kanban/{$task->id}");

    ModuleAssertions::assertAudited($task, 'updated');
});

it('gives the second of two saves from the same form a 409 and keeps the first', function (): void {
    $task = Task::factory()->create();
    ModuleAssertions::actingAsLevelWith(['kanban.view', 'kanban.edit']);

    put("/admin/kanban/{$task->id}", taskInput(['lock_version' => 0]))->assertRedirect();
    put("/admin/kanban/{$task->id}", taskInput(['lock_version' => 0]))->assertStatus(409);

    expect($task->fresh()?->lock_version)->toBe(1);
});

it('moves a kanban to the trash and audits it', function (): void {
    $task = Task::factory()->create();
    ModuleAssertions::actingAsLevelWith(['kanban.view', 'kanban.delete']);

    delete("/admin/kanban/{$task->id}")->assertRedirect();

    expect($task->fresh()?->trashed())->toBeTrue();
    ModuleAssertions::assertAudited($task, 'deleted');
});

it('deletes the selected records in one audit batch', function (): void {
    [$first, $second] = Task::factory()->count(2)->create()->all();
    ModuleAssertions::actingAsLevelWith(['kanban.view', 'kanban.delete']);

    delete('/admin/kanban', ['ids' => [$first->id, $second->id]])->assertRedirect();

    expect(Task::query()->count())->toBe(0)
        ->and(ImmutableActivity::query()->where('event', 'deleted')->pluck('batch_uuid')->unique()->filter())->toHaveCount(1);
});

it('lets only Super Admin see the trash and restore', function (): void {
    $task = Task::factory()->create();
    $task->delete();
    ModuleAssertions::actingAsLevelWith(['kanban.view', 'kanban.delete']);

    get('/admin/kanban/trash')->assertForbidden();
    post('/admin/kanban/trash/restore', ['ids' => [$task->id]])->assertForbidden();

    ModuleAssertions::actingAsSuperAdmin();
    post('/admin/kanban/trash/restore', ['ids' => [$task->id]])->assertRedirect();

    expect($task->fresh()?->trashed())->toBeFalse();
    ModuleAssertions::assertAudited($task, 'restored');
});
